const results = [];

for (const item of $input.all()) {
  const pages = item.json.pages || [];

  for (const page of pages) {
    const images = page.images || [];

    for (const image of images) {
      const raw = image.image_base64 || '';
      const base64 = raw.replace(/^data:image\/[a-zA-Z]+;base64,/, '');

      results.push({
        json: {
          page_index: page.index,
          image_id: image.id || null,
        },
        binary: {
          data: {
            data: Buffer.from(base64, 'base64'),
            mimeType: 'image/jpeg',
            fileName: `ocr_page${page.index}_${image.id || 'img'}.jpg`,
          },
        },
      });
    }
  }
}

return results;

// Handle multiple OCR documents with multiple images per document
// Each document can have many images, and we need to match the right Gemini captions

// Get all OCR outputs from the HTTP Request node
const ocrOutputs = $('HTTP Request - Mistral Doc OCR').all();

// Get all Gemini captions from the Analyze image node
const geminiCaptions = $input.all();

// Create a flat list to track which caption corresponds to which image
// We'll use the order of execution to match them
let captionIndex = 0;

const results = [];

// Loop through each OCR document
for (const ocrItem of ocrOutputs) {
  const ocrOutput = ocrItem.json;

  // Clone the pages array for this document
  const updatedPages = JSON.parse(JSON.stringify(ocrOutput.pages));

  // Process each page in this document
  updatedPages.forEach(page => {
    if (page.images && page.images.length > 0) {
      let markdown = page.markdown;

      // Process each image in the page
      page.images.forEach(img => {
        const imageRef = `![${img.id}](${img.id})`;

        // Check if this image reference exists in the markdown
        if (markdown.includes(imageRef)) {
          // Get the corresponding Gemini caption
          if (captionIndex < geminiCaptions.length) {
            const geminiCaption = geminiCaptions[captionIndex].json.content.parts[0].text || "Image description not available";

            // Insert caption right after the image reference
            const captionText = `\n*Image Description: ${geminiCaption}*\n`;
            markdown = markdown.replace(imageRef, imageRef + captionText);

            captionIndex++;
          }
        }
      });

      // Update the page markdown
      page.markdown = markdown;
    }
  });

  // Add the updated document to results
  results.push({
    json: {
      ...ocrOutput,
      pages: updatedPages
    }
  });
}

return results;

// Markdown Section Splitter
// V3.1 - with Hierarchy, Page Merge & Metadata Enrichment

// Input:  Document(s) with `pages[].markdown`
// Output: Array of section objects ready for vector DB insertion

function parseMarkdownWithHierarchy(text, headingStack, lastSection) {
  const lines = text.split('\n');
  const sections = [];
  // let currentSection = lastSection ? { ...lastSection } : null;
  let currentSection = null; // start fresh on each page; no shallow copy

  for (const line of lines) {
    const headingMatch = line.match(/^(#{1,6})\s+(.+)$/);

    if (headingMatch) {
      // Save previous section if it exists
      if (currentSection) sections.push(currentSection);

      const level = headingMatch[1].length;
      const title = headingMatch[2].trim();

      // Remove headings of same or deeper level
      while (headingStack.length > 0 && headingStack[headingStack.length - 1].level >= level) {
        headingStack.pop();
      }

      // Add current heading to stack
      headingStack.push({ level, title });

      // Build hierarchical path
      const hierarchicalTitle = headingStack.map(h => h.title).join(' > ');

      // New section
      currentSection = {
        level,
        title,
        hierarchicalTitle,
        heading: line,
        content: []
      };
    } else if (line.trim()) {
      // Normal text — attach to current section or create one
      if (!currentSection) {
        const hierarchicalTitle = headingStack.length
          ? headingStack.map(h => h.title).join(' > ')
          : 'Introduction';
        currentSection = {
          level: headingStack.length ? headingStack[headingStack.length - 1].level : 0,
          title: headingStack.length ? headingStack[headingStack.length - 1].title : 'Introduction',
          hierarchicalTitle,
          heading: '',
          content: []
        };
      }
      currentSection.content.push(line);
    }
  }

  if (currentSection) sections.push(currentSection);

  return { sections, headingStack, lastSection: currentSection };
}

// --- Main Execution ---
const results = [];
let globalSectionId = 1;
let headingStack = [];
let lastSection = null;

for (const doc of $('Merge Metadata').all()) {
  const pages = doc.json.pages || [];
  const docId = doc.json.docId || 'Unknown Document ID';
  const docUrl = doc.json.docUrl || 'Unknown Document URL';
  const docName = doc.json.docName || 'Unknown Document Name';
  const source = doc.json.source || 'Unknown Source';
  const team = doc.json.team || 'Unknown Team';
  const createdAt = doc.json.createdAt || 'Unknown Created Time';

  // Reset per document
  headingStack = [];
  lastSection = null;

  pages.forEach((page, pageIndex) => {
    const text = page.markdown || '';
    const pageNumber = pageIndex + 1;
    const baseMeta = {
      docId,
      docName,
      docUrl,
      source,
      team,
      createdAt
    };

    const { sections, headingStack: updatedStack, lastSection: newLastSection } =
      parseMarkdownWithHierarchy(text, headingStack, lastSection);

    headingStack = updatedStack;
    lastSection = newLastSection;

    // --- Case 1: Page has no headings ---
    if (sections.length === 0 && text.trim()) {
      const sectionTitle = headingStack.length
        ? headingStack.map(h => h.title).join(' > ')
        : `Page ${pageNumber}`;

      const lastResult = results[results.length - 1];
      if (
        lastResult &&
        lastResult.json.metadata.sectionTitle === sectionTitle &&
        lastResult.json.metadata.docId === docId
      ) {
        // Merge into previous
        lastResult.json.text += '\n' + text.trim();
        lastResult.json.metadata.pageRange = `${lastResult.json.metadata.pageRange}-${pageNumber}`;
      } else {
        results.push({
          json: {
            sectionId: globalSectionId++,
            text: text.trim(),
            metadata: {
              ...baseMeta,
              sectionTitle,
              sectionLevel: headingStack.length
                ? headingStack[headingStack.length - 1].level
                : 0,
              parentSection:
                headingStack.length > 1
                  ? headingStack.slice(0, -1).map(h => h.title).join(' > ')
                  : null,
              pageRange: `${pageNumber}`
            }
          }
        });
      }
      return; // skip to next page
    }

    // --- Case 2: Page has parsed sections ---
    for (const section of sections) {
      let sectionText = section.heading;
      if (section.content.length > 0) {
        sectionText += '\n' + section.content.join('\n');
      }

      // If same sectionTitle repeated -> merge content
      const lastResult = results[results.length - 1];
      if (
        lastResult &&
        lastResult.json.metadata.sectionTitle === section.hierarchicalTitle &&
        lastResult.json.metadata.docId === docId
      ) {
        lastResult.json.text += '\n' + sectionText.trim();
        lastResult.json.metadata.pageRange = `${lastResult.json.metadata.pageRange}-${pageNumber}`;
      } else {
        results.push({
          json: {
            sectionId: globalSectionId++,
            text: sectionText.trim(),
            metadata: {
              ...baseMeta,
              sectionTitle: section.hierarchicalTitle,
              sectionLevel: section.level,
              parentSection:
                section.hierarchicalTitle.includes(' > ')
                  ? section.hierarchicalTitle.split(' > ').slice(0, -1).join(' > ')
                  : null,
              pageRange: `${pageNumber}`
            }
          }
        });
      }
    }
  });
}

return results;

// Second Code Node: Check character count and chunk if necessary
// Input: Sections from first node
// Output: Chunks (may be split if too long, maintaining sectionTitle)

// Get configurable parameters (now in CHARACTERS, not words)
const CHUNK_SIZE = $('Set Chunk ID, Chunk Size & Overlap (Characters)').first().json.chunk_size || 1000;  // characters
const OVERLAP_SIZE = $('Set Chunk ID, Chunk Size & Overlap (Characters)').first().json.chunk_overlap || 0;  // characters

// Count characters in text
function countCharacters(text) {
  return text.trim().length;
}

// Count words in text (for metadata)
function countWords(text) {
  return text.trim().split(/\s+/).filter(word => word.length > 0).length;
}

// Chunk text by characters using sliding window if it exceeds chunk size
function chunkByCharacters(text, chunkSize, overlapSize) {
  const trimmedText = text.trim();
  const chunks = [];

  // If content fits within chunk size, return as single chunk
  if (trimmedText.length <= chunkSize) {
    return [trimmedText];
  }

  // If content exceeds chunk size, apply sliding window
  let startIndex = 0;

  while (startIndex < trimmedText.length) {
    const endIndex = Math.min(startIndex + chunkSize, trimmedText.length);
    let chunkText = trimmedText.substring(startIndex, endIndex);

    // Try to break at natural boundaries (sentence, paragraph, or word)
    if (endIndex < trimmedText.length) {
      // Look for natural break points within the last 20% of the chunk
      const breakZoneStart = Math.floor(chunkSize * 0.8);
      const breakZone = chunkText.substring(breakZoneStart);

      // Try to find break points in order of preference
      const breakPoints = [
        breakZone.lastIndexOf('\n\n'),  // Paragraph break
        breakZone.lastIndexOf('. '),    // Sentence end
        breakZone.lastIndexOf('.\n'),   // Sentence end with newline
        breakZone.lastIndexOf('! '),    // Exclamation
        breakZone.lastIndexOf('? '),    // Question
        breakZone.lastIndexOf('\n'),    // Line break
        breakZone.lastIndexOf(' ')      // Word boundary
      ];

      // Use the first valid break point found
      for (const breakPoint of breakPoints) {
        if (breakPoint > 0) {
          chunkText = chunkText.substring(0, breakZoneStart + breakPoint + 1).trim();
          break;
        }
      }
    }

    if (chunkText) {
      chunks.push(chunkText);
    }

    // Calculate next start position with overlap
    const actualChunkLength = chunkText.length;
    if (startIndex + actualChunkLength >= trimmedText.length) {
      break;
    }

    startIndex += actualChunkLength - overlapSize;

    // Ensure we make progress
    if (startIndex <= 0) {
      startIndex = actualChunkLength - overlapSize;
    }
  }

  return chunks;
}

// Main execution
const results = [];
let globalChunkId = parseInt(($('Set Chunk ID, Chunk Size & Overlap (Characters)').first().json.chunk_id));

for (const item of $input.all()) {
  const sectionData = item.json;
  const text = sectionData.text || '';
  const charCount = countCharacters(text);
  const wordCount = countWords(text);

  // Check if section needs chunking
  if (charCount <= CHUNK_SIZE) {
    // Section is small enough, keep as is
    results.push({
      json: {
        chunkId: globalChunkId++,
        text: text,
        metadata: sectionData.metadata,
        sectionTitle: sectionData.sectionTitle,
        sectionId: sectionData.sectionId,
        isSubChunk: false,
        subChunkIndex: 0,
        totalSubChunks: 1,
        charCount: charCount,
        wordCount: wordCount
      }
    });
  } else {
    // Section is too large, chunk it
    const textChunks = chunkByCharacters(text, CHUNK_SIZE, OVERLAP_SIZE);

    textChunks.forEach((chunkText, index) => {
      results.push({
        json: {
          chunkId: globalChunkId++,
          text: chunkText,
          metadata: sectionData.metadata,
          sectionTitle: sectionData.sectionTitle, // Keep the same hierarchical title
          sectionId: sectionData.sectionId,
          isSubChunk: true,
          subChunkIndex: index,
          totalSubChunks: textChunks.length,
          charCount: countCharacters(chunkText),
          wordCount: countWords(chunkText)
        }
      });
    });
  }
}

return results;
